window.AUTH=window.AUTH||{};window.AUTH["24-856"]={"d":"24-856","id":"2025/24-856","n":"Cisco Systems, Inc. v. Doe I","briefs":[{"k":"petitioner","label":"Brief of petitioners Cisco Systems, Inc., et al.","date":"2026-02-18","url":"https://www.supremecourt.gov/DocketPDF/24/24-856/396570/20260218115211423_24-856%20-%20Cisco%20Br%20for%20Petrs.pdf","side":"pet","n":49},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2026-02-25","url":"https://www.supremecourt.gov/DocketPDF/24/24-856/397322/20260225165613681_24-856tsacUnitedStates.pdf","side":"us","n":31},{"k":"respondent","label":"Brief of respondents Doe I, et al.","date":"2026-03-20","url":"https://www.supremecourt.gov/DocketPDF/24/24-856/401497/20260320163800247_24-856%20Brief%20for%20Respondents.pdf","side":"res","n":57},{"k":"reply","label":"Reply of petitioners Cisco Systems, Inc., et al.","date":"2026-04-15","url":"https://www.supremecourt.gov/DocketPDF/24/24-856/404489/20260415094601358_Cisco%20reply%20brief%20for%20petitioners%20-%2024-856.pdf","side":"pet","n":34}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/609us1r57_db8e.pdf","tr":true,"items":[{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"by":{"0":"20, 33","2":"39","3":"5, 6"}},{"t":"case","label":"American Insurance Association v. Garamendi","cite":"539 U.S. 396","y":2003,"id":"2002/02-722","sc":1,"by":{"0":"21"},"q":[{"src":"brief","b":0,"text":"has recognized the President’s ‘vast share of responsibility for the conduct of our foreign relations.’","cite":"539 U.S. 396, 414"}]},{"t":"case","label":"Bivens v. Six Unknown Federal Narcotics Agents","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"by":{"0":"20","1":"16, 17, 21"},"q":[{"src":"argument","who":"Justice Gorsuch","text":"Well, and -- and what lessons should we take from cases like Egbert in the Bivens context and -- and -- and our decisions on Teague about these doors that have been left open?"},{"src":"argument","who":"Mr. Gannon","text":"And -- but, because the Court now understands better than the First Congress did -- and I understand the uncomfort -- discomfort with that, that it -- that recognizing a cause of action is a legislative endeavor that it's going to do only cautiously -- the Court has repeatedly said in these ATS cases and in the -- and in the Bivens cases that it's not going to extend any further if there's any reason counseling hesitation."},{"src":"argument","who":"Justice Sotomayor","text":"So Bivens and -- Bivens and Egbert don't help us because, whether it's express or implied causes of action, they've been created for the Blackstone Three, correct?"}]},{"t":"case","label":"Boim v. Holy Land Foundation","cite":"549 F.3d 685","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/549/685/","by":{"0":"29"},"q":[{"src":"brief","b":0,"text":"statutory silence on the subject of secondary liability means there is none.","cite":"549 F.3d 685, 689"}]},{"t":"case","label":"Central Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"by":{"0":"4, 11-17, 28-32, 40, 42, 44, 45","1":"3, 4, 8, 11, 12, 21-24, 29, 31-33","2":"3, 10-11, 31-33, 41, 49-51","3":"2, 3, 7-11"},"q":[{"src":"brief","b":0,"text":"knew how to impose aiding and abetting liability when it chose to do so.","cite":"511 U.S. at 176"},{"src":"brief","b":0,"text":"who do not engage in the proscribed activities at all, but who give a degree of aid to those who do.","cite":"511 U.S. at 176"},{"src":"brief","b":1,"text":"persons who do not engage in the proscribed activities at all, but who give a degree of aid to those who do.","cite":"511 U.S. 164, 176"},{"src":"brief","b":1,"text":"aiding and abetting liability reaches persons who do not engage in the proscribed activities at all, but who give a degree of aid to those who do.","cite":"511 U.S. 164, 176"},{"src":"brief","b":3,"text":"Congress knew how to impose aiding and abetting liability when it chose to do so,","cite":"511 U.S. at 176"},{"src":"brief","b":3,"text":"[t]he fact that Congress chose to impose some forms of secondary liability, but not others, indicates a deliberate congressional choice with which the courts should not interfere.","cite":"511 U.S. at 184"}]},{"t":"case","label":"Central Virginia Community College v. Katz","cite":"546 U.S. 356","y":2006,"id":"2005/04-885","sc":1,"by":{"0":"24"}},{"t":"case","label":"Chicago & Southern Air Lines v. Waterman S.S. Corp.","cite":"333 U.S. 103","y":1948,"id":"scdb/1947-037","sc":1,"by":{"0":"22"},"q":[{"src":"brief","b":0,"text":"are delicate, complex, and involve large elements of prophecy.","cite":"333 U.S. 103, 111"}]},{"t":"case","label":"City Select Auto Sales Inc. v. David Randall Associates, Inc.","cite":"885 F.3d 154","y":2018,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/885/154/","by":{"0":"29"}},{"t":"case","label":"Correctional Services Corp. v. Malesko","cite":"534 U.S. 61","y":2001,"id":"2001/00-860","sc":1,"by":{"0":"20","1":"20","2":"39"},"q":[{"src":"brief","b":1,"text":"‘a question for Congress, not [the courts], to decide.’","cite":"534 U.S. 61, 72"}]},{"t":"case","label":"Doe v. Exxon Mobil Corp.","cite":"654 F.3d 11","y":2011,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/654/11/","by":{"0":"28, 34-36, 40","1":"12, 22, 28, 29","2":"32","3":"9, 12, 17"},"q":[{"src":"brief","b":0,"text":"there can be no civil aiding and abetting liability unless Congress expressly provides for it.","cite":"654 F.3d 11, 87"},{"src":"brief","b":0,"text":"if an ATS suit would harm the Nation’s foreign relations—as assessed and explained by the Department of State or Department of Justice as representative of the President of the United States—then the courts have no business ignoring that statement of interest, thereby threatening the Nation’s foreign relations and thwarting Congress’s intent in the ATS.","cite":"654 F.3d at 89"},{"src":"brief","b":1,"text":"provides no aiding and abetting liability.","cite":"654 F.3d 11, 87"},{"src":"brief","b":1,"text":"there can be no civil aiding and abetting liability unless Congress expressly provides for it.","cite":"654 F.3d at 87"},{"src":"brief","b":3,"text":"liability for aiding and abetting torture and extrajudicial killing does not exist under the TVPA.","cite":"654 F.3d at 87"}]},{"t":"case","label":"Edwards v. Vannoy","cite":"593 U.S. 255","y":2021,"id":"2020/19-5807","sc":1,"by":{"0":"27","1":"10, 17, 18"},"q":[{"src":"brief","b":0,"text":"[c]ontinuing to articulate a theoretical exception that never actually applies in practice offers false hope to [litigants], distorts the law, misleads judges, and wastes the resources of * * * counsel * * * and courts.","cite":"593 U.S. 255, 272"},{"src":"brief","b":1,"text":"misleads litigants and judges, and needlessly expends the scarce resources of","cite":"593 U.S. at 275"}]},{"t":"case","label":"Egbert v. Boule","cite":"596 U.S. 482","y":2022,"id":"2021/21-147","sc":1,"by":{"0":"20-22, 31","1":"9, 16, 17, 20, 27","3":"4, 5"},"q":[{"src":"brief","b":0,"text":"the Constitution’s separation of legislative and judicial power.","cite":"596 U.S. 482"},{"src":"brief","b":0,"text":"refrain from creating such a remedy.","cite":"596 U.S. at 491, 496"},{"src":"brief","b":1,"text":"‘tension between’ judicially created causes of action and ‘the Constitution’s separation of legislative and judicial power.’","cite":"596 U.S. 482, 491"},{"src":"brief","b":1,"text":"creating a cause of action is a legislative endeavor.","cite":"596 U.S. at 491"},{"src":"brief","b":3,"text":"there is any rational reason (even one) to think that Congress is better suited","cite":"596 U.S. at 491, 496"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"[h]ome-grown causes of action are diffcult to reconcile with `the Constitution's separation of legislative and judicial power.'","cite":"596 U. S. 482, 491"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"`[e]ven a single sound reason to defer to Congress is enough.'","cite":"596 U. S., at 491"},{"src":"argument","who":"Mr. Shanmugam","text":"And this Court, in its most recent ATS cases, has looked to that body of case law, the broader body of case law concerning implied causes of action, and there, under Egbert, the question is whether there is any sound reason to believe that Congress might not want to recognize this type of liability, and the fact that these concerns arise so frequently in these sorts of cases is sufficient to satisfy that standard."},{"src":"argument","who":"Justice Gorsuch","text":"Well, and -- and what lessons should we take from cases like Egbert in the Bivens context and -- and -- and our decisions on Teague about these doors that have been left open?"},{"src":"argument","who":"Justice Sotomayor","text":"So Bivens and -- Bivens and Egbert don't help us because, whether it's express or implied causes of action, they've been created for the Blackstone Three, correct?"}]},{"t":"case","label":"Halberstam v. Welch","cite":"705 F.2d 472","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/705/472/","by":{"0":"42","2":"48"},"q":[{"src":"argument","who":"Mr. Shanmugam","text":"Circuit in the Halberstam case, the common law largely confined aiding-and-abetting liability to isolated acts of adolescents in rural society."}]},{"t":"case","label":"Hernandez v. Mesa","cite":"589 U.S. 93","y":2020,"id":"2019/17-1678","sc":1,"by":{"0":"20, 21, 23","2":"39","3":"4, 5"},"q":[{"src":"brief","b":0,"text":"might have been different if they were decided today.","cite":"589 U.S. 93"},{"src":"brief","b":2,"text":"a lawmaking body that enacts a provision that creates a right . . . may not wish to pursue the provision’s purpose to the extent of authorizing private suits for damages.","cite":"589 U.S. 93, 100"},{"src":"brief","b":3,"text":"may not wish to pursue the provision’s purpose to the extent of authorizing private suits for damages.","cite":"589 U.S. at 100"}]},{"t":"case","label":"Jesner v. Arab Bank, PLC","cite":"584 U.S. 241","y":2018,"id":"2017/16-499","sc":1,"by":{"0":"6, 7, 18, 19, 21-23, 26, 27, 31, 33-38","1":"2, 5, 6, 9, 10, 13-17, 20, 21, 25-28","2":"23, 34, 37","3":"4, 5, 7, 13, 15-16"},"q":[{"src":"brief","b":0,"text":"the political branches of the Government.","cite":"584 U.S. at 274"},{"src":"brief","b":0,"text":"[i]n light of the foreign-policy and separation-of- powers concerns inherent in ATS litigation, there is an argument that a proper application of Sosa would preclude courts from ever recognizing any new causes of action under the ATS.","cite":"584 U.S. 241, 265"},{"src":"brief","b":1,"text":"if there are sound reasons to think Congress might doubt the efficacy or necessity","cite":"584 U.S. 241, 264"},{"src":"brief","b":1,"text":"the only cause of action under the ATS created by Congress rather than the courts.","cite":"584 U.S. at 265"},{"src":"brief","b":3,"text":"an essential foundation for human rights.","cite":"584 U.S. at 269"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"point of [a new ATS cause of action is] to vindicate `a norm of international character.'","cite":"584 U. S., at 284"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"`if there are sound reasons to think Congress Sotomayor, J., dissenting might doubt the effcacy or necessity of a damages remedy.'","cite":"584 U. S. 241, 264"},{"src":"argument","who":"Mr. Shanmugam","text":"And, indeed, I think Justice Sotomayor's dissent in Jesner supports our view because, to the extent that she construed Footnote 20 of Sosa to suggest that you still take domestic law into account when analyzing these questions about the available defendants, we would obviously point to Central Bank."},{"src":"argument","who":"Mr. Shanmugam","text":"So, if you were looking for a straight-line way to write an opinion in this case, one way to do that would be simply to say at the second step, much as in Jesner, that these sorts of claims, these sorts of aiding-and-abetting claims, as a categorical matter are likely to raise these sorts of foreign policy concerns, as well as the broader separation of powers concerns that underlie this Court's reluctance to recognize implied causes of action."},{"src":"argument","who":"Justice Sotomayor","text":"Assuming I don't -- I don't agree with you because, in Kiobel and Jesner, we called it a ruling, but putting aside that that's what we called it, you are basically saying, if it's a holding, overrule it, correct?"}]},{"t":"case","label":"Kimble v. Marvel Entertainment, LLC","cite":"576 U.S. 446","y":2015,"id":"2014/13-720","sc":1,"by":{"0":"25","1":"18","2":"37"},"q":[{"src":"brief","b":2,"text":"Overruling precedent is never a small matter.","cite":"576 U.S. 446, 455"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"it is not alone suffcient that we would decide a case differently now than we did then.","cite":"576 U. S. 446, 455–456"}]},{"t":"case","label":"Kiobel v. Royal Dutch Petroleum Co.","cite":"569 U.S. 108","y":2013,"id":"2011/10-1491","sc":1,"by":{"0":"5, 10, 21, 22, 26, 30, 33, 38","1":"11, 13, 14, 16, 22-24, 26","2":"10, 23, 35, 23","3":"11"},"q":[{"src":"brief","b":0,"text":"provide judicial relief to foreign officials injured in the United States.","cite":"569 U.S. 108, 123"},{"src":"brief","b":0,"text":"identifying such a norm is only the beginning of defining a cause of action.","cite":"569 U.S. at 117"},{"src":"brief","b":1,"text":"the question is not what Congress has done but instead what courts may do.","cite":"569 U.S. 108, 116"},{"src":"brief","b":1,"text":"constrain courts considering causes of action that may be brought under the ATS.","cite":"569 U.S. at 116"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"the danger of unwarranted judicial interference in the conduct of foreign policy is magnifed in Page Proof Pending Publication th[is] context.","cite":"569 U. S., at 116"},{"src":"argument","who":"Justice Sotomayor","text":"Assuming I don't -- I don't agree with you because, in Kiobel and Jesner, we called it a ruling, but putting aside that that's what we called it, you are basically saying, if it's a holding, overrule it, correct?"},{"src":"argument","who":"Justice Sotomayor","text":"After Kiobel, that number dropped precipitously, all right? So it's not as if this is such a large number of cases that it's overwhelming the courts below."},{"src":"argument","who":"Mr. Gannon","text":"The second mode of analysis that -- that -- that we're talking about under Sosa step 2 is the one that the Court employed in both Kiobel and in Jesner."}]},{"t":"case","label":"Kirch v. Embarq Management Co.","cite":"702 F.3d 1245","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/702/1245/","by":{"0":"29"}},{"t":"case","label":"Loper Bright Enterprises v. Raimondo","cite":"603 U.S. 369","y":2024,"id":"2023/22-451","sc":1,"by":{"0":"26","3":"6"},"q":[{"src":"brief","b":0,"text":"to gamble not only that the doctrine will be invoked, but also that it will produce readily foreseeable outcomes and the stability that comes with them.","cite":"603 U.S. 369, 410"},{"src":"brief","b":3,"text":"invites different results in like cases.","cite":"603 U.S. at 408"},{"src":"argument","who":"Mr. Shanmugam","text":"That methodology has proven to be unworkable, and, as this Court did in Edwards versus Vannoy and Loper Bright, when confronted with similarly unworkable methodologies, this Court should now reject it."}]},{"t":"case","label":"Mohamad v. Palestinian Authority","cite":"566 U.S. 449","y":2012,"id":"2011/11-88","sc":1,"by":{"0":"7, 40, 45","1":"29, 32","2":"41, 52","3":"19, 20"},"q":[{"src":"brief","b":0,"text":"reliance on legislative history is unnecessary in light of [a] statute’s unambiguous language.","cite":"566 U.S. at 458"},{"src":"brief","b":1,"text":"officer who gives an order to torture.","cite":"566 U.S. at 458"},{"src":"brief","b":2,"text":"the TVPA contemplates liability against officers who do not personally execute the torture or extrajudicial killing.","cite":"566 U.S. at 458"}]},{"t":"case","label":"Nestlé USA, Inc. v. Doe","cite":"593 U.S. 628","y":2021,"id":"2020/19-416","sc":1,"by":{"0":"17-19, 21-27","1":"2, 5, 15, 16, 19, 20, 25","2":"22, 33","3":"3, 4, 5"},"q":[{"src":"brief","b":1,"text":"permitting courts to recognize a ‘narrow class’ of implied rights of action.","cite":"593 U.S. 628"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"In the years since, this Court has read Sosa to announce a two-step test for recognizing the availability of a cause of action under the ATS.","cite":"593 U. S. 628, 648"}]},{"t":"case","label":"Oetjen v. Central Leather Co.","cite":"246 U.S. 297","y":1918,"id":"scdb/1917-085","sc":1,"by":{"0":"21"},"q":[{"src":"brief","b":0,"text":"The propriety of what may be done in the exercise of this political power is not subject to judicial inquiry or decision.","cite":"246 U.S. 297, 302"}]},{"t":"case","label":"Presbyterian Church of Sudan v. Talisman Energy, Inc.","cite":"2005 WL 2082846","y":2005,"court":"S.D.N.Y. Aug. 30","by":{"0":"35"},"q":[{"src":"brief","b":0,"text":"peaceful resolution of Sudan’s internal disputes","cite":"2005 WL 2082846"}]},{"t":"case","label":"Sarei v. Rio Tinto, PLC","cite":"487 F.3d 1193","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/487/1193/","by":{"0":"35"},"q":[{"src":"brief","b":0,"text":"its relations with the United States.","cite":"487 F.3d 1193, 1199"}]},{"t":"case","label":"Seminole Tribe of Florida v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"by":{"0":"24"}},{"t":"case","label":"Smith & Wesson Brands, Inc. v. Estados Unidos Mexicanos","cite":"605 U.S. 280","y":2025,"id":"2024/23-1141","sc":1,"by":{"0":"32"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"by":{"0":"3-7, 11, 18-27, 31-34, 36, 37, 44","1":"2-5, 7, 9-11, 13-20, 23, 25-27","2":"1-2, 8-10, 13, 15-16, 18, 22-23, 25, 28, 30, 33-34, 36-40, 52-54","3":"1, 2, 4-7, 11, 14, 16"},"q":[{"src":"brief","b":0,"text":"its inability to cause infractions of treaties, or of the law of nations, to be punished.","cite":"542 U.S. at 716"},{"src":"brief","b":0,"text":"assault against an ambassador * * * if not adequately redressed could rise to an issue of war.","cite":"542 U.S. at 715"},{"src":"brief","b":1,"text":"creat[es] no new causes of action.","cite":"542 U.S. 692, 713, 724"},{"src":"brief","b":1,"text":"the creation of private federal causes of action for violations of customary international law.","cite":"542 U.S. at 747"},{"src":"brief","b":2,"text":"[T]he torturer has become—like the pirate and slave trader before him—hostis humani generis, an enemy of all mankind.","cite":"542 U.S. at 732"},{"src":"brief","b":2,"text":"The Sosa Court . . . held that in certain narrow circumstances courts may recognize a common-law cause of action for claims based on the present-day law-of-nations in addition to the ‘historical paradigms familiar when § 1350 was enacted.’","cite":"542 U.S. at 732"},{"src":"brief","b":3,"text":"claim a limit on the power of foreign governments over their own citizens,","cite":"542 U.S. at 727"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"inconsistent with [the court's] obligation to exercise `great caution in adapting the law of nations to private rights.'","cite":"542 U. S., at 728"},{"src":"argument","who":"Mr. Shanmugam","text":"As to the ATS, Respondents primarily rely on Sosa, which left open the possibility that courts could recognize new causes of action drawn from modern international law under the ATS."},{"src":"argument","who":"Justice Thomas","text":"Can you think of any cause of action that Sosa would permit?"},{"src":"argument","who":"Mr. Shanmugam","text":"We believe that Sosa permits two types of causes of action, first, a cause of action for the three core offenses contemplated by the First Congress."}]},{"t":"case","label":"Tel-Oren v. Libyan Arab Republic","cite":"726 F.2d 774","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/726/774/","by":{"0":"25"},"q":[{"src":"argument","who":"Mr. Gannon","text":"I -- I take the point that to the extent that the door is open, Congress doesn't have a clear incentive to go through and start saying this is the one that we think ought to be codified, as it did with the TVPA after Filartiga and Tel-Oren."}]},{"t":"case","label":"Twitter, Inc. v. Taamneh","cite":"598 U.S. 471","y":2023,"id":"2022/21-1496","sc":1,"by":{"0":"32, 33, 42","1":"21, 24, 29, 30","2":"42-43","3":"8"},"q":[{"src":"brief","b":0,"text":"must perform a wrongful act that causes an injury.","cite":"598 U.S. at 486"},{"src":"brief","b":0,"text":"g[ave] knowing and substantial assistance to the primary tortfeasor.","cite":"598 U.S. at 491"},{"src":"brief","b":1,"text":"aiding and abetting is inherently a rule of secondary liability.","cite":"598 U.S. 471, 494"},{"src":"brief","b":1,"text":"an organization that had [already] been designated [by the Secretary of State] as a foreign terrorist organization.","cite":"598 U.S. at 484"},{"src":"brief","b":2,"text":"in a wrongful act so as to help ‘make it succeed.’","cite":"598 U.S. 471, 493"},{"src":"argument","who":"Mr. Hoffman","text":"Well, the -- the -- what I would say to that is that as your decision in Twitter laid out in terms of the long history of aiding and abetting in criminal -- the criminal context, there's an equally long history of accessorial liability and aiding-and-abetting liability in the context of the law of nations, which, from our standpoint, in terms of enforcing this statute is different from anything that existed in terms of civil aiding-and-abetting liability."}]},{"t":"case","label":"United States v. Hatatley","cite":"130 F.3d 1399","y":1997,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/130/1399/","by":{"0":"42"},"q":[{"src":"brief","b":0,"text":"even though [the aiding and abetting] was not the ultimate case of the harm.","cite":"130 F.3d 1399, 1406"}]},{"t":"case","label":"Wooden v. United States","cite":"595 U.S. 360","y":2022,"id":"2021/20-5279","sc":1,"by":{"0":"45"},"q":[{"src":"brief","b":0,"text":"the problems with legislative history are well rehearsed.","cite":"595 U.S. 360, 381"}]},{"t":"case","label":"Youngstown Sheet & Tube Co. v. Sawyer","cite":"343 U.S. 579","y":1952,"id":"1940-1955/343us579","sc":1,"by":{"0":"21"}},{"t":"case","label":"Ziglar v. Abbasi","cite":"582 U.S. 120","y":2017,"id":"2016/15-1358","sc":1,"by":{"0":"20","1":"16","3":"4"}},{"t":"case","label":"Zivotofsky ex rel. Zivotofsky v. Kerry","cite":"576 U.S. 1","y":2015,"id":"2014/13-628","sc":1,"by":{"0":"7"}},{"t":"const","label":"Article I, Section 8, Clause 3","clauses":[["commerce","Commerce Clause"]],"text":"To regulate Commerce with foreign Nations, and among the several States, and with the Indian Tribes;","by":{"0":"21"}},{"t":"const","label":"Article II","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"],["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"],["take-care","Take Care Clause"],["impeachment","Impeachment"]],"by":{"0":"21"}},{"t":"law","label":"Pub. L. No. 101-519","by":{"0":"29"}},{"t":"usc","label":"28 U.S.C. § 1350","url":"https://www.law.cornell.edu/uscode/text/28/1350","stext":{"head":"§1350. Alien's action for tort","paras":[[0,"The district courts shall have original jurisdiction of any civil action by an alien for a tort only, committed in violation of the law of nations or a treaty of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1350?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2-7, 9-19, 21, 23, 24, 26-39, 2, 4, 7, 9-11, 14-16, 23, 36, 39-41, 43-46","1":"1, 5, 24, 1, 2, 4-8, 11-13, 20, 27-32","2":"1, 3, 8, 33, 54, 11-12, 33, 37","3":"1-16, 21, 3, 5, 12, 16-21"},"q":[{"src":"brief","b":0,"text":"shall have original jurisdiction of any civil action by an alien for a tort only, committed in violation of the law of nations or a treaty of the United States.","cite":"28 U.S.C. 1350"},{"src":"brief","b":0,"text":"district courts shall have original jurisdiction of any civil action by an alien for a tort only, committed in violation of the law of nations or a treaty of the United States.","cite":"28 U.S.C. 1350"},{"src":"brief","b":1,"text":"The district courts shall have original jurisdiction of any civil action by an alien for a tort only, committed in violation of the law of nations or a treaty of the United States.","cite":"28 U.S.C. 1350"},{"src":"brief","b":1,"text":"tort[s] * * * committed in violation of the law of nations,","cite":"28 U.S.C. 1350"},{"src":"brief","b":2,"text":"for a tort only, committed in violation of the law of nations.","cite":"28 U.S.C. § 1350"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"[a]n individual who . . . subjects an individual to torture shall, in a civil action, be liable for damages to that individual.","cite":"28 U. S. C. § 1350"}]},{"t":"law","label":"Electronic Communications Privacy Act, Pub. L. No. 99-508","url":"https://www.govinfo.gov/link/statute/100/1848","by":{"0":"29"}},{"t":"law","label":"Pub. L. No. 101-246","url":"https://www.govinfo.gov/link/statute/104/15","by":{"0":"7","2":"29"}},{"t":"usc","label":"47 U.S.C. § 227","url":"https://www.law.cornell.edu/uscode/text/47/227","by":{"0":"29"}},{"t":"law","label":"Pub. L. No. 108-193","url":"https://www.govinfo.gov/link/plaw/108/public/193","by":{"0":"23"}},{"t":"law","label":"Pub. L. No. 116-145","url":"https://www.govinfo.gov/link/plaw/116/public/145","by":{"0":"23"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","subs":["(a)"],"stext":{"head":"§2. Principals","paras":[[0,"(a) Whoever commits an offense against the United States or aids, abets, counsels, commands, induces or procures its commission, is punishable as a principal."],[0,"(b) Whoever willfully causes an act to be done which if directly performed by him or another would be an offense against the United States, is punishable as a principal."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2?type=usc&year=mostrecent&link-type=html"},"by":{"0":"29, 40","2":"11, 44-45","3":"20"},"q":[{"src":"argument","who":"Mr. Hoffman","text":"Well, what -- what our -- what our position is -- Section 2 of the TVPA says that an individual who subjects another person to torture is liable under the TVPA."}]},{"t":"usc","label":"18 U.S.C. § 2333","url":"https://www.law.cornell.edu/uscode/text/18/2333","subs":["(d)(2)","(a)"],"stext":{"head":"§2333. Civil remedies","paras":[[0,"(a) Action and Jurisdiction.—Any national of the United States injured in his or her person, property, or business by reason of an act of international terrorism, or his or her estate, survivors, or heirs, may sue therefor in any appropriate district court of the United States and shall recover threefold the damages he or she sustains and the cost of the suit, including attorney's fees."],[0,"(b) Estoppel Under United States Law.—A final judgment or decree rendered in favor of the United States in any criminal proceeding under section 1116, 1201, 1203, or 2332 of this title or section 46314, 46502, 46505, or 46506 of title 49 shall estop the defendant from denying the essential allegations of the criminal offense in any subsequent civil proceeding under this section."],[0,"(c) Estoppel Under Foreign Law.—A final judgment or decree rendered in favor of any foreign state in any criminal proceeding shall, to the extent that such judgment or decree may be accorded full faith and credit under the law of the United States, estop the defendant from denying the essential allegations of the criminal offense in any subsequent civil proceeding under this section."],[0,"(d) Liability.—"],[1,"(1) Definition.—In this subsection, the term \"person\" has the meaning given the term in section 1 of title 1."],[1,"(2) Liability.—In an action under subsection (a) for an injury arising from an act of international terrorism committed, planned, or authorized by an organization that had been designated as a foreign terrorist organization under section 219 of the Immigration and Nationality Act (8 U.S.C. 1189), as of the date on which such act of international terrorism was committed, planned, or authorized, liability may be asserted as to any person who aids and abets, by knowingly providing substantial assistance, or who conspires with the person who committed such an act of international terrorism."],[0,"(e) Use of Blocked Assets to Satisfy Judgments of U.S. Nationals.—For purposes of section 201 of the Terrorism Risk Insurance Act of 2002 (28 U.S.C. 1610 note), in any action in which a national of the United States has obtained a judgment against a terrorist party pursuant to this section, the term \"blocked asset\" shall include any asset of that terrorist party (including the blocked assets of any agency or instrumentality of that party) seized or frozen by the United States under section 805(b) of the Foreign Narcotics Kingpin Designation Act (21 U.S.C. 1904(b))."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2333?type=usc&year=mostrecent&link-type=html"},"by":{"0":"40","1":"12, 29, 12, 29, 30","2":"45"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"2"}},{"t":"reg","label":"15 C.F.R. § 742.7","url":"https://www.ecfr.gov/current/title-15/section-742.7","by":{"0":"8","3":"13"}},{"t":"case","label":"Chavez v. Carranza","cite":"559 F.3d 486","y":2009,"url":"https://www.courtlistener.com/c/F.3d/559/486/","by":{"1":"32","2":"44, 52"},"q":[{"src":"brief","b":2,"text":"reasonable and necessary measures to prevent","cite":"559 F.3d at 499"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"failed to take all necessary and reasonable measures to prevent","cite":"559 F. 3d 486, 499"}]},{"t":"case","label":"Erie Railroad Co. v. Tompkins","cite":"304 U.S. 64","y":1938,"id":"1900-1940/304us64","sc":1,"by":{"1":"14, 16"},"q":[{"src":"argument","who":"Mr. Shanmugam","text":"And our submission is that this aspect of Sosa in a post-Erie world, recognizing new causes of action, was wrong at the time, but recent developments have made clear that it is no longer tenable, namely, this Court's view in cases involving implied causes of action that this is quintessentially a legislative endeavor."},{"src":"argument","who":"Mr. Gannon","text":"Well, I -- I -- I do think that's a bit of a puzzle because of the sort of Erie revolution. This is the thing that -- that Sosa talked about."},{"src":"argument","who":"Mr. Gannon","text":"I think, at the -- in the pre-Erie sense, there was an understanding that it was out there. It was the brooding omnipresence. Maybe you discovered new bits of it."}]},{"t":"case","label":"Goldey v. Fields","cite":"606 U.S. 942","y":2025,"id":"scdb/2024-068","sc":1,"by":{"1":"17"}},{"t":"case","label":"Hernández v. Mesa","cite":"589 U.S. 93","y":2020,"url":"https://supreme.justia.com/cases/federal/us/589/93/","sc":1,"by":{"1":"9, 16, 17, 27"}},{"t":"case","label":"Herrera v. Wyoming","cite":"587 U.S. 329","y":2019,"id":"2018/17-532","sc":1,"by":{"1":"18"}},{"t":"case","label":"Hilao v. Estate of Marcos","cite":"103 F.3d 767","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/103/767/","by":{"1":"32"},"q":[{"src":"brief","b":1,"text":"holds a superior responsible for the actions of subordinates.","cite":"103 F.3d 767, 777"}]},{"t":"case","label":"Teague v. Lane","cite":"489 U.S. 288","y":1989,"id":"1988/87-5259","sc":1,"by":{"1":"17"},"q":[{"src":"argument","who":"Justice Gorsuch","text":"Well, and -- and what lessons should we take from cases like Egbert in the Bivens context and -- and -- and our decisions on Teague about these doors that have been left open?"}]},{"t":"usc","label":"18 U.S.C. § 2331","url":"https://www.law.cornell.edu/uscode/text/18/2331","by":{"1":"29"}},{"t":"usc","label":"22 U.S.C. § 7101","url":"https://www.law.cornell.edu/uscode/text/22/7101","by":{"1":"28"}},{"t":"usc","label":"18 U.S.C. § 1595","url":"https://www.law.cornell.edu/uscode/text/18/1595","subs":["(a)"],"by":{"1":"28"}},{"t":"usc","label":"8 U.S.C. § 1189","url":"https://www.law.cornell.edu/uscode/text/8/1189","subs":["(a)(1)","(d)(4)"],"by":{"1":"30, 30"}},{"t":"usc","label":"15 U.S.C. § 78j","url":"https://www.law.cornell.edu/uscode/text/15/78j","subs":["(b)"],"stext":{"head":"§78j. Manipulative and deceptive devices","paras":[[0,"It shall be unlawful for any person, directly or indirectly, by the use of any means or instrumentality of interstate commerce or of the mails, or of any facility of any national securities exchange—"],[1,"(a)(1) To effect a short sale, or to use or employ any stop-loss order in connection with the purchase or sale, of any security other than a government security, in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Paragraph (1) of this subsection shall not apply to security futures products."],[1,"(b) To use or employ, in connection with the purchase or sale of any security registered on a national securities exchange or any security not so registered, or any securities-based swap agreement 1 any manipulative or deceptive device or contrivance in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(c)(1) To effect, accept, or facilitate a transaction involving the loan or borrowing of securities in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Nothing in paragraph (1) may be construed to limit the authority of the appropriate Federal banking agency (as defined in section 1813(q) of title 12), the National Credit Union Administration, or any other Federal department or agency having a responsibility under Federal law to prescribe rules or regulations restricting transactions involving the loan or borrowing of securities in order to protect the safety and soundness of a financial institution or to protect the financial system from systemic risk."],[0,"Rules promulgated under subsection (b) that prohibit fraud, manipulation, or insider trading (but not rules imposing or specifying reporting or recordkeeping requirements, procedures, or standards as prophylactic measures against fraud, manipulation, or insider trading), and judicial precedents decided under subsection (b) and rules promulgated thereunder that prohibit fraud, manipulation, or insider trading, shall apply to security-based swap agreements to the same extent as they apply to securities. Judicial precedents decided under section 77q(a) of this title and sections 78i, 78o, 78p, 78t, and 78u–1 of this title, and judicial precedents decided under applicable rules promulgated under such sections, shall apply to security-based swap agreements to the same extent as they apply to securities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78j?type=usc&year=mostrecent&link-type=html"},"by":{"1":"31","2":"32"}},{"t":"case","label":"Am. Isuzu Motors, Inc. v. Ntsebeza","cite":"553 U.S. 1028","y":2008,"url":"https://supreme.justia.com/cases/federal/us/553/1028/","sc":1,"by":{"2":"32"},"q":[{"src":"argument","who":"Mr. Gannon","text":"And I was mentioning the South Africa cases in the 2000s, and in American Isuzu, where we filed an amicus brief about aiding-and-abetting liability, the South African government expressed concerns that having these cases litigated in the United States about apartheid and -- and grievous things that happened under apartheid was inconsistent with the Truth and Reconciliation Commission."}]},{"t":"case","label":"Auer v. Robbins","cite":"519 U.S. 452","y":1997,"id":"1996/95-897","sc":1,"by":{"2":"42"}},{"t":"case","label":"Aziz v. Alcolac, Inc","cite":"658 F.3d 388","y":2011,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/658/388/","by":{"2":"32"}},{"t":"case","label":"Balintulo v. Daimler AG","cite":"727 F.3d 174","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/727/174/","by":{"2":"22"}},{"t":"case","label":"Biden v. Nebraska","cite":"600 U.S. 477","y":2023,"id":"2022/22-506","sc":1,"by":{"2":"50","3":"8"}},{"t":"case","label":"Boniface v. Viliena","cite":"145 F.4th 98","y":2025,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.4th/145/98/","by":{"2":"41, 45"}},{"t":"case","label":"Bucklew v. Precythe","cite":"587 U.S. 119","y":2019,"id":"2018/17-8151","sc":1,"by":{"2":"37"}},{"t":"case","label":"Cabello v. Fernandez-Larios","cite":"402 F.3d 11487","y":2005,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/402/11487/","by":{"2":"41"}},{"t":"case","label":"Chowdhury v. Worldtel Bangladesh Holding, Ltd.","cite":"746 F.3d 42","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/746/42/","by":{"2":"47"}},{"t":"case","label":"Comcast Corp. v. Nat’l Ass’n of African Am-Owned Media","cite":"589 U.S. 327","y":2020,"url":"https://supreme.justia.com/cases/federal/us/589/327/","sc":1,"by":{"2":"48"}},{"t":"case","label":"Davis v. Monroe Cnty. Bd. of Educ.","cite":"526 U.S. 629","y":1999,"id":"1998/97-843","sc":1,"by":{"2":"42"}},{"t":"case","label":"Dubin v. United States","cite":"599 U.S. 110","y":2023,"id":"2022/22-10","sc":1,"by":{"2":"46"}},{"t":"case","label":"Ernst & Ernst v. Hochfelder","cite":"425 U.S. 185","y":1976,"id":"1975/74-1042","sc":1,"by":{"2":"32"}},{"t":"case","label":"Filartiga v. Pena-Irala","cite":"630 F.2d 876","y":1980,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/630/876/","by":{"2":"25, 40, 25"},"q":[{"src":"argument","who":"Mr. Gannon","text":"And so I'm -- I think that we're reconciling the Court's modern understanding of its appropriate role in the separation of powers with the -- with the fact that the First Congress only wrote a jurisdictional authorization with -- with this expectation that there was a possibility of causes of action being recognized, but now we know Congress can do that. And Congress knows that it's supposed to do that. And that's why Congress enacted the TVPA, because it was codifying Filartiga."},{"src":"argument","who":"Mr. Gannon","text":"It's about the actual perpetrator acting under color of foreign law. And so Congress did codify that result after it was questioned whether the ATS even allowed Filartiga."},{"src":"argument","who":"Mr. Gannon","text":"-- Congress has -- has spoken to lots of specific questions in the TVPA that allow actions like Filartiga to proceed."}]},{"t":"case","label":"FTC v. Mandel Bros., Inc.","cite":"359 U.S. 385","y":1959,"id":"1958/234","sc":1,"by":{"2":"46"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"582 U.S. 79","y":2017,"id":"2016/16-349","sc":1,"by":{"2":"50"},"q":[{"src":"brief","b":2,"text":"to apply, not amend, the work of the People’s representatives.","cite":"582 U.S. 79, 90"}]},{"t":"case","label":"Jones v. Hendrix","cite":"599 U.S. 465","y":2023,"id":"2022/21-857","sc":1,"by":{"2":"50"}},{"t":"case","label":"Khulumani v. Barclay Nat’l Bank Ltd.","cite":"504 F.3d 254","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/504/254/","by":{"2":"32"}},{"t":"case","label":"King v. St. Vincent’s Hosp.","cite":"502 U.S. 215","y":1991,"id":"1991/90-889","sc":1,"by":{"2":"51"}},{"t":"case","label":"Nye & Nissen v. United States","cite":"336 U.S. 613","y":1949,"id":"scdb/1948-062","sc":1,"by":{"2":"42"}},{"t":"case","label":"Patterson v. McLean Credit Union","cite":"491 U.S. 164","y":1989,"id":"scdb/1988-115","sc":1,"by":{"2":"38"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"irreconcilable with competing legal doctrines or policies,","cite":"491 U. S., at 173"}]},{"t":"case","label":"Southwest Airlines Co. v. Saxon","cite":"596 U.S. 450","y":2022,"id":"2021/21-309","sc":1,"by":{"2":"44"},"q":[{"src":"brief","b":2,"text":"different term denotes a different idea.","cite":"596 U.S. 450, 457-58"}]},{"t":"case","label":"Stanley v. City of Stanford","cite":"606 U.S. 46","y":2025,"id":"2024/23-997","sc":1,"by":{"2":"52"},"q":[{"src":"brief","b":2,"text":"[W]hen a document uses a term in one place and a materially different term in another, ‘the presumption is that the different term denotes a different idea.’","cite":"606 U.S. 46, 53"}]},{"t":"case","label":"Stoneridge Inv. Partners, LLC v. Scientific-Atlanta","cite":"552 U.S. 148","y":2008,"id":"2007/06-43","sc":1,"by":{"2":"50"}},{"t":"case","label":"United States v. Ross","cite":"27 F. Cas. 899","y":1813,"court":"C.C.D.R.I.","url":"https://www.courtlistener.com/c/F.%20Cas./27/899/","by":{"2":"14"}},{"t":"case","label":"Wisconsin Cent. Ltd. v. United States","cite":"585 U.S. 274","y":2018,"id":"2017/17-530","sc":1,"by":{"2":"41"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"2":"30"}},{"t":"usc","label":"18 U.S.C. § 2340A","url":"https://www.law.cornell.edu/uscode/text/18/2340A","stext":{"head":"§2340A. Torture","paras":[[0,"(a) Offense.—Whoever outside the United States commits or attempts to commit torture shall be fined under this title or imprisoned not more than 20 years, or both, and if death results to any person from conduct prohibited by this subsection, shall be punished by death or imprisoned for any term of years or for life."],[0,"(b) Jurisdiction.—There is jurisdiction over the activity prohibited in subsection (a) if—"],[1,"(1) the alleged offender is a national of the United States; or"],[1,"(2) the alleged offender is present in the United States, irrespective of the nationality of the victim or alleged offender."],[0,"(c) Conspiracy.—A person who conspires to commit an offense under this section shall be subject to the same penalties (other than the penalty of death) as the penalties prescribed for the offense, the commission of which was the object of the conspiracy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2340A?type=usc&year=mostrecent&link-type=html"},"by":{"2":"44","3":"20"},"q":[{"src":"brief","b":2,"text":"commit[] or attempt[] to commit torture.","cite":"18 U.S.C. § 2340A(a)"}]},{"t":"usc","label":"18 U.S.C. § 2441","url":"https://www.law.cornell.edu/uscode/text/18/2441","by":{"2":"44"}},{"t":"usc","label":"22 U.S.C. § 2304","url":"https://www.law.cornell.edu/uscode/text/22/2304","stext":{"head":"§2304. Human rights and security assistance","paras":[[0,"(a) Observance of human rights as principal goal of foreign policy; implementation requirements"],[0,"(1) The United States shall, in accordance with its international obligations as set forth in the Charter of the United Nations and in keeping with the constitutional heritage and traditions of the United States, promote and encourage increased respect for human rights and fundamental freedoms throughout the world without distinction as to race, sex, language, or religion. Accordingly, a principal goal of the foreign policy of the United States shall be to promote the increased observance of internationally recognized human rights by all countries."],[0,"(2) Except under circumstances specified in this section, no security assistance may be provided to any country the government of which engages in a consistent pattern of gross violations of internationally recognized human rights. Security assistance may not be provided to the police, domestic intelligence, or similar law enforcement forces of a country, and licenses may not be issued under the Export Administration Act of 1979 for the export of crime control and detection instruments and equipment to a country, the government of which engages in a consistent pattern of gross violations of internationally recognized human rights unless the President certifies in writing to the Speaker of the House of Representatives and the chairman of the Committee on Foreign Relations of the Senate and the chairman of the Committee on Banking, Housing, and Urban Affairs of the Senate (when licenses are to be issued pursuant to the Export Administration Act of 1979).1 that extraordinary circumstances exist warranting provision of such assistance and issuance of such licenses. Assistance may not be provided under part V of this subchapter to a country the government of which engages in a consistent pattern of gross violations of internationally recognized human rights unless the President certifies in writing to the Speaker of the House of Representatives and the chairman of the Committee on Foreign Relations of the Senate that extraordinary circumstances exist warranting provision of such assistance."],[0,"(3) In furtherance of paragraphs (1) and (2), the President is directed to formulate and conduct international security assistance programs of the United States in a manner which will promote and advance human rights and avoid identification of the United States, through such programs, with governments which deny to their people internationally recognized human rights and fundamental freedoms, in violation of international law or in contravention of the policy of the United States as expressed in this section or otherwise."],[0,"(4) In determining whether the government of a country engages in a consistent pattern of gross violations of internationally recognized human rights, the President shall give particular consideration to whether the government—"],[1,"(A) has engaged in or tolerated particularly severe violations of religious freedom, as defined in section 6402 of this title; or"],[1,"(B) has failed to undertake serious and sustained efforts to combat particularly severe violations of religious freedom when such efforts could have been reasonably undertaken."],[0,"(b) Report by Secretary of State on practices of proposed recipient countries; considerations"],[0,"The Secretary of State shall transmit to the Congress, as part of the presentation materials for security assistance programs proposed for each fiscal year, a full and complete report, prepared with the assistance of the Assistant Secretary of State for Democracy, Human Rights, and Labor and with the assistance of the Ambassador at Large for International Religious Freedom, with respect to practices regarding the observance of and respect for internationally recognized human rights in each country proposed as a recipient of security assistance. Wherever applicable, such report shall include consolidated information regarding the commission of war crimes, crimes against humanity, and evidence of acts that may constitute genocide (as defined in article 2 of the Convention on the Prevention and Punishment of the Crime of Genocide and modified by the United States instrument of ratification to that convention and section 2(a) of the Genocide Convention Implementation Act of 1987). Wherever applicable, such report shall include information on practices regarding coercion in population control, including coerced abortion and involuntary sterilization. Such report shall also include, wherever applicable, information on violations of religious freedom, including particularly severe violations of religious freedom (as defined in section 6402 of this title). Wherever applicable, such report shall include a description of the nature and extent of acts of anti-Semitism and anti-Semitic incitement that occur, including the descriptions of such acts required under section 2151n(d)(8) of this title. Such report shall also include, for each country with respect to which the report indicates that extrajudicial killings, torture, or other serious violations of human rights have occurred in the country, the extent to which the United States has taken or will take action to encourage an end to such practices in the country. Each report under this section shall list the votes of each member of the United Nations Commission on Human Rights on all country-specific and thematic resolutions voted on at the Commission's annual session during the period covered during the preceding year. Each report under this section shall also include (i) wherever applicable, a description of the nature and extent of the compulsory recruitment and conscription of individuals under the age of 18 by armed forces of the government of the country, government-supported paramilitaries, or other armed groups, the participation of such individuals in such groups, and the nature and extent that such individuals take a direct part in hostilities, (ii) what steps, if any, taken by the government of the country to eliminate such practices, and (iii) such other information related to the use by such government of individuals under the age of 18 as soldiers, as determined to be appropriate by the Secretary of State. Each report under this section shall describe the extent to which each country has extended protection to refugees, including the provision of first asylum and resettlement. In determining whether a government falls within the provisions of subsection (a)(3) and in the preparation of any report or statement required under this section, consideration shall be given to—"],[1,"(1) the relevant findings of appropriate international organizations, including nongovernmental organizations, such as the International Committee of the Red Cross; and"],[1,"(2) the extent of cooperation by such government in permitting an unimpeded investigation by any such organization of alleged violations of internationally recognized human rights."],[0,"(c) Congressional request for information; information required; 30-day period; failure to supply information; termination or restriction of assistance"],[0,"(1) Upon the request of the Senate or the House of Representatives by resolution of either such House, or upon the request of the Committee on Foreign Relations of the Senate or the Committee on Foreign Affairs of the House of Representatives, the Secretary of State shall, within thirty days after receipt of such request, transmit to both such committees a statement, prepared with the assistance of the Assistant Secretary of State for Democracy, Human Rights, and Labor, with respect to the country designated in such request, setting forth—"],[1,"(A) all the available information about observance of and respect for human rights and fundamental freedom in that country, and a detailed description of practices by the recipient government with respect thereto;"],[1,"(B) the steps the United States has taken to—"],[2,"(i) promote respect for and observance of human rights in that country and discourage any practices which are inimical to internationally recognized human rights, and"],[2,"(ii) publicly or privately call attention to, and disassociate the United States and any security assistance provided for such country from, such practices;"],[1,"(C) whether, in the opinion of the Secretary of State, notwithstanding any such practices—"],[2,"(i) extraordinary circumstances exist which necessitate a continuation of security assistance for such country, and, if so, a description of such circumstances and the extent to which such assistance should be continued (subject to such conditions as Congress may impose under this section), and"],[2,"(ii) on all the facts it is in the national interest of the United States to provide such assistance; and"],[1,"(D) such other information as such committee or such House may request."],[0,"(2)(A) A resolution of request under paragraph (1) of this subsection shall be considered in the Senate in accordance with the provisions of section 601(b) of the International Security Assistance and Arms Export Control Act of 1976."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/2304?type=usc&year=mostrecent&link-type=html"},"by":{"2":"24"},"q":[{"src":"brief","b":2,"text":"to promote the increased observance of internationally recognized human rights by all countries.","cite":"22 U.S.C. § 2304(a)(1)"}]},{"t":"usc","label":"28 U.S.C. § 1658","url":"https://www.law.cornell.edu/uscode/text/28/1658","by":{"2":"54"}},{"t":"law","label":"Justice Against Sponsors of Terrorism Act, Pub. L. No. 114-222","url":"https://www.govinfo.gov/link/plaw/114/public/222","by":{"2":"45"}},{"t":"law","label":"Pub. L. No. 102-256","url":"https://www.govinfo.gov/link/statute/106/73","by":{"2":"3, 8, 11-12, 31, 39-52, 54"}},{"t":"case","label":"Case Concerning Application on the Prevention and Punishment of the Crime of Genocide (Bosnia & Herzegovina v. Serbia & Montenegro), Judgment","cite":"2007 I.C.J. Rep. 43","y":2007,"court":"Feb. 26","url":"https://www.courtlistener.com/c/I.C.J.%20Rep./2007/43/","by":{"2":"21"},"q":[{"src":"argument","who":"Chief Justice Roberts","text":"We will hear argument this morning in Case 24-856, Cisco Systems versus Doe. Mr. Shanmugam. ORAL ARGUMENT OF KANNON K. SHANMUGAM ON BEHALF OF THE PETITIONERS"}]},{"t":"case","label":"Br. of Amicus Curiae Ministry of Commerce of the People’s Republic of China, Animal Sci. Prods., Inc. v. Hebei Welcome Pharma. Co. Ltd.","cite":"585 U.S. 33","y":2018,"url":"https://supreme.justia.com/cases/federal/us/585/33/","sc":1,"by":{"2":"23"}},{"t":"case","label":"Al Shimari v. CACI Premier Technology, Inc.","cite":"2026 WL 693110","y":2026,"court":"4th Cir. Mar. 12","by":{"3":"7, 15"},"q":[{"src":"brief","b":3,"text":"federal courts should not create new causes of action,","cite":"2026 WL 693110"},{"src":"brief","b":3,"text":"consider whether creating a new cause of action might create separation of powers concerns.","cite":"2026 WL 693110"}]},{"t":"case","label":"Atascadero State Hospital v. Scanlon","cite":"473 U.S. 234","y":1985,"id":"1984/84-351","sc":1,"by":{"3":"17"}},{"t":"case","label":"Department of Agriculture Rural Development Rural Housing Service v. Kirtz","cite":"601 U.S. 42","y":2024,"id":"2023/22-846","sc":1,"by":{"3":"17"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"hardly means it was `foreclose[d] . . . from using different language to accomplish th[e] same goal.'","cite":"601 U. S. 42, 52"}]},{"t":"case","label":"Doe v. Qi","cite":"349 F. Supp. 2d 1258","y":2004,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/349/1258/","by":{"3":"16"}},{"t":"case","label":"(I) Cases—continued: Edwards v. Vannoy","cite":"593 U.S. 255","y":2021,"url":"https://supreme.justia.com/cases/federal/us/593/255/","sc":1,"by":{"3":"6"},"q":[{"src":"brief","b":3,"text":"no stare decisis values would be served","cite":"593 U.S. 255, 274"}]},{"t":"case","label":"Gregory v. Ashcroft","cite":"501 U.S. 452","y":1991,"id":"1990/90-50","sc":1,"by":{"3":"17"}},{"t":"case","label":"Leegin Creative Leather Products, Inc. v. PSKS, Inc.","cite":"551 U.S. 877","y":2007,"id":"2006/06-480","sc":1,"by":{"3":"6"}},{"t":"case","label":"Medina v. Planned Parenthood South Atlantic","cite":"606 U.S. 357","y":2025,"id":"2024/23-1275","sc":1,"by":{"3":"20"}},{"t":"case","label":"Samantar v. Yousuf","cite":"560 U.S. 305","y":2010,"id":"2009/08-1555","sc":1,"by":{"3":"14"}},{"t":"case","label":"State Oil Co. v. Khan","cite":"522 U.S. 3","y":1997,"id":"1997/96-871","sc":1,"by":{"3":"6"},"q":[{"src":"brief","b":3,"text":"adapting to changed circumstances and the lessons of accumulated experience.","cite":"522 U.S. at 20"}]},{"t":"reg","label":"85 Fed. Reg. 4176","url":"https://www.govinfo.gov/link/fr/85/4176","by":{"3":"13"}},{"t":"reg","label":"85 Fed. Reg. 63,009","url":"https://www.govinfo.gov/link/fr/85/63009","by":{"3":"13"}},{"t":"reg","label":"89 Fed. Reg. 28,594","url":"https://www.govinfo.gov/link/fr/89/28594","by":{"3":"13"}},{"t":"reg","label":"89 Fed. Reg. 34,680","url":"https://www.govinfo.gov/link/fr/89/34680","by":{"3":"13"}},{"t":"reg","label":"90 Fed. Reg. 47,170","url":"https://www.govinfo.gov/link/fr/90/47170","by":{"3":"13"}}]};